    "description": "ワハット・アル・カラマ(尊厳のオアシス)は、UAEのために犠牲となった兵士や殉教者を称える記念公園です。31枚のアルミニウムパネルが互いに寄り添うように配置された記念パビリオンは、UAE連邦の団結を象徴し、その中心には永遠の炎が灯されています。シェイク・ザイード・グランド・モスクを望む位置にあり、訪問者にとって理想的な組み合わせとなっています。美しい庭園と水辺のスペースは、静かな瞑想へと誘います。4.7の評価を得ており、訪問者は厳粛な雰囲気と見事な建築を称賛しています。UAEの異なる側面を発見したいなら、必見の場所です。入場は無料で、ビジターセンターではUAEの歴史について学ぶことができます。",
